/**
 * Guard-denial circuit breaker tests (#3422).
 *
 * The guard was never wrong in the incident this closes — on 2026-08-10 a
 * session re-sent one byte-identical denied command 8 consecutive times and
 * the block was correct every time. What was missing was anything in the
 * rendered denial that (a) told the caller the exact command that WOULD work,
 * or (b) distinguished the 8th denial from the 1st. These tests assert both
 * are now present, and that both degrade to the plain block on any failure.
 *
 * `worktree-scan` is mocked so candidate worktrees are deterministic; its own
 * on-disk contract is covered by lib/worktree-scan.test.ts against real fs.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import type { HookContext, HookInput } from '../../types.js';
import { gitValidator, buildWorktreeRewrite } from '../../pretool/bash/git-validator.js';
import { NOOP_CTX } from '../../lib/context.js';

vi.mock('node:child_process', () => ({
  execFileSync: vi.fn(() => ''),
}));

vi.mock('../../lib/git-head.js', () => ({
  readBranchFromHead: vi.fn(),
  readBranchOr: vi.fn(),
}));

vi.mock('../../lib/worktree-scan.js', () => ({
  listLinkedWorktrees: vi.fn(() => []),
  resolveCommonGitDir: vi.fn(),
}));

import { execFileSync } from 'node:child_process';
import { readBranchOr } from '../../lib/git-head.js';
import { listLinkedWorktrees } from '../../lib/worktree-scan.js';
import { _resetBranchCacheForTesting } from '../../lib/git.js';

const PROJECT_DIR = '/test/project';
const WORKTREE = '/test/project/.worktrees/ghlabel';
const SESSION_ID = 'denial-test-session';

function input(command: string, overrides: Partial<HookInput> = {}): HookInput {
  return {
    tool_name: 'Bash',
    session_id: SESSION_ID,
    project_dir: PROJECT_DIR,
    tool_input: { command },
    ...overrides,
  };
}

function mainCtx(): HookContext {
  return { ...NOOP_CTX, branch: 'main', projectDir: PROJECT_DIR };
}

/** Deny reason text, or '' when the call was not a deny. */
function denyText(command: string, overrides: Partial<HookInput> = {}): string {
  const r = gitValidator(input(command, overrides), mainCtx());
  return r.continue === false ? (r.stopReason ?? '') : '';
}

function withWorktrees(...wts: Array<{ path: string; branch: string }>): void {
  vi.mocked(listLinkedWorktrees).mockReturnValue(
    wts.map((w) => ({ ...w, activityMs: 0 })),
  );
}

let tmpHome: string;
let prevHome: string | undefined;

beforeEach(() => {
  tmpHome = mkdtempSync(join(tmpdir(), 'gv-deny-'));
  prevHome = process.env.HOME;
  process.env.HOME = tmpHome;
  delete process.env.ORCHESTKIT_PROTECTED_BRANCHES;

  vi.mocked(execFileSync).mockReset();
  vi.mocked(execFileSync).mockReturnValue('');
  vi.mocked(readBranchOr).mockReset();
  vi.mocked(readBranchOr).mockImplementation((_dir: string, fallback: string) => fallback);
  vi.mocked(listLinkedWorktrees).mockReset();
  vi.mocked(listLinkedWorktrees).mockReturnValue([]);
  _resetBranchCacheForTesting();
});

afterEach(() => {
  if (prevHome === undefined) delete process.env.HOME;
  else process.env.HOME = prevHome;
  rmSync(tmpHome, { recursive: true, force: true });
});

// =============================================================================
// (a) Worktree-shaped rewrite
// =============================================================================

describe('worktree-shaped denial carries a copyable rewrite', () => {
  it('names the exact git -C command for the one feature-branch worktree', () => {
    withWorktrees({ path: WORKTREE, branch: 'fix/ghlabel' });

    const text = denyText('git add -A && git commit -m "fix: x"');

    expect(text).toContain('BLOCKED');
    expect(text).toContain(`git -C ${WORKTREE} add -A && git commit -m "fix: x"`);
  });

  it('does not tell the operator to create a branch they already have', () => {
    withWorktrees({ path: WORKTREE, branch: 'fix/ghlabel' });

    // The pre-#3422 text said "1. git checkout -b …" unconditionally, which is
    // actively wrong advice when a feature-branch worktree is already checked
    // out — following it creates a second branch and does not unblock.
    expect(denyText('git commit -m "fix: x"')).not.toContain('git checkout -b');
  });

  it('keeps the standard workflow text when there is no worktree', () => {
    withWorktrees();

    const text = denyText('git commit -m "fix: x"');
    expect(text).toContain('Required workflow');
    expect(text).toContain('git checkout -b');
    expect(text).not.toContain('git -C');
  });

  it('ignores worktrees that are themselves on a protected branch', () => {
    withWorktrees({ path: '/test/project/.worktrees/trunk', branch: 'main' });

    const text = denyText('git commit -m "fix: x"');
    expect(text).toContain('Required workflow');
    expect(text).not.toContain('/test/project/.worktrees/trunk');
  });

  it('ignores a detached worktree, which has no branch to suggest', () => {
    withWorktrees({ path: '/test/project/.worktrees/ctl', branch: '' });
    expect(denyText('git commit -m "fix: x"')).toContain('Required workflow');
  });

  it('lists alternatives when several worktrees qualify', () => {
    withWorktrees(
      { path: '/wt/a', branch: 'fix/a' },
      { path: '/wt/b', branch: 'fix/b' },
      { path: '/wt/c', branch: 'fix/c' },
    );

    const text = denyText('git commit -m "fix: x"');
    expect(text).toContain('git -C /wt/a commit -m "fix: x"');
    expect(text).toContain('Other worktrees on feature branches');
    expect(text).toContain('/wt/b  [fix/b]');
    expect(text).toContain('/wt/c  [fix/c]');
  });

  it('diagnoses a resolved directory that holds no readable branch', () => {
    withWorktrees();
    // `~/...` is not expanded, so it absolutizes into a path that cannot exist.
    // Reporting that is far more actionable than a bare BLOCKED.
    const text = denyText('cd ~/coding/repo/.worktrees/x && git commit -m "fix: x"');
    expect(text).toContain('no git branch is readable there');
    expect(text).toContain("a leading '~' is not expanded");
  });

  it('still blocks a real protected-branch commit — no rewrite is an escape', () => {
    withWorktrees({ path: WORKTREE, branch: 'fix/ghlabel' });
    const r = gitValidator(input('git commit -m "fix: x"'), mainCtx());
    expect(r.continue).toBe(false);
  });
});

describe('buildWorktreeRewrite', () => {
  it('preserves the original arguments verbatim', () => {
    expect(buildWorktreeRewrite('git push -u origin HEAD', '/wt/a')).toBe(
      'git -C /wt/a push -u origin HEAD',
    );
  });

  it('refuses to rewrite a command that already names its own -C', () => {
    // The caller was explicit about where git runs, so the protected branch we
    // blocked on really is the branch there. Overriding that would be wrong.
    expect(buildWorktreeRewrite('git -C /elsewhere commit -m "x"', '/wt/a')).toBeNull();
  });
});

// =============================================================================
// (b) Repetition circuit breaker
// =============================================================================

describe('repeated identical denials escalate', () => {
  const CMD = 'git add -A && git commit -m "fix: x"';

  it('says nothing about repetition on the first denial', () => {
    withWorktrees({ path: WORKTREE, branch: 'fix/ghlabel' });
    const first = denyText(CMD);
    expect(first).not.toContain('IDENTICAL DENIAL');
  });

  it('leads the SECOND identical denial with a loud banner', () => {
    withWorktrees({ path: WORKTREE, branch: 'fix/ghlabel' });
    denyText(CMD);
    const second = denyText(CMD);

    expect(second.startsWith('SECOND IDENTICAL DENIAL')).toBe(true);
    expect(second).toContain('do not re-send this command');
    expect(second).toContain('denied 2 times');
  });

  it('renders the second denial differently from the first', () => {
    withWorktrees({ path: WORKTREE, branch: 'fix/ghlabel' });
    expect(denyText(CMD)).not.toBe(denyText(CMD));
  });

  it('keeps counting and numbering past the second', () => {
    withWorktrees();
    denyText(CMD);
    denyText(CMD);
    expect(denyText(CMD)).toContain('IDENTICAL DENIAL #3');
    expect(denyText(CMD)).toContain('IDENTICAL DENIAL #4');
  });

  it('offers a read-only diagnostic instead of another attempt', () => {
    withWorktrees();
    denyText(CMD);
    expect(denyText(CMD)).toContain(`git -C ${PROJECT_DIR} branch --show-current`);
  });

  it('does not escalate when the command changes shape', () => {
    withWorktrees({ path: WORKTREE, branch: 'fix/ghlabel' });
    denyText(CMD);
    denyText(CMD);
    // Adjusting the command is the desired response; it must not read as more
    // of the same loop.
    const adjusted = denyText('git commit -m "fix: x" --amend');
    expect(adjusted).not.toContain('IDENTICAL DENIAL');
  });

  it('still carries the rewrite alongside the escalation', () => {
    withWorktrees({ path: WORKTREE, branch: 'fix/ghlabel' });
    denyText(CMD);
    const second = denyText(CMD);
    expect(second).toContain(`git -C ${WORKTREE} add -A && git commit -m "fix: x"`);
  });

  it('does not count allowed commands as denials', () => {
    withWorktrees();
    // A feature-branch session is never blocked, so nothing should accumulate.
    const featureCtx: HookContext = { ...NOOP_CTX, branch: 'fix/x', projectDir: PROJECT_DIR };
    gitValidator(input(CMD), featureCtx);
    gitValidator(input(CMD), featureCtx);

    expect(denyText(CMD)).not.toContain('IDENTICAL DENIAL');
  });
});

