describe('enrichment never breaks the guard', () => {
  it('still denies when worktree enumeration throws', () => {
    vi.mocked(listLinkedWorktrees).mockImplementation(() => {
      throw new Error('fs exploded');
    });

    // A crashing hook is worse than a terse one: CC surfaces it as a tool
    // error, and the block is what actually protects the branch.
    expect(() => gitValidator(input('git commit -m "x"'), mainCtx())).not.toThrow();
  });
});
